/****************************************************************************
 * Name: gt911_hardware_reset
 *
 * Description:
 *   Perform GT911 hardware reset sequence using RST and INT pins.
 *   The GT911 samples the INT pin level during reset to select its
 *   I2C address: INT=LOW -> 0x5d, INT=HIGH -> 0x24.
 *
 *   On ESP32-S3-BOX-3, RST is shared with DISPLAY_RST (GPIO 48).
 *   This function must run BEFORE LCD init so that the GPIO 48 toggle
 *   does not reset an already-configured LCD controller.
 *
 * Input Parameters:
 *   None.
 *
 * Returned Value:
 *   Zero (OK) on success; a negated errno value on failure.
 *
 ****************************************************************************/

static int gt911_hardware_reset(void)
{
  /* Configure INT pin as output LOW to select I2C address 0x5d.
   * GT911 samples INT during reset release to determine its address.
   */

  esp32s3_configgpio(TOUCHSCEEN_INT, OUTPUT);
  esp32s3_gpiowrite(TOUCHSCEEN_INT, false);

  /* Configure RST pin as output and assert reset (LOW) */

  esp32s3_configgpio(DISPLAY_RST, OUTPUT);
  esp32s3_gpiowrite(DISPLAY_RST, false);
  nxsig_usleep(GT911_RESET_HOLD_US);

  /* Release reset (HIGH) — GT911 boots and samples INT for address */

  esp32s3_gpiowrite(DISPLAY_RST, true);
  nxsig_usleep(GT911_RESET_DELAY_US);

  /* Reconfigure INT pin as input for future interrupt use */

  esp32s3_configgpio(TOUCHSCEEN_INT, INPUT_PULLUP);

  return OK;
}

