static void ili9342c_configure(struct ili9341_lcd_s *lcd,
                               uint8_t cmd,
                               uint8_t data_bytes,
                               const uint8_t *data)
{
  lcd->select(lcd);
  lcd->sendcmd(lcd, cmd);
  if (data_bytes)
    {
      for (int i = 0; i < data_bytes; i++)
        {
          lcd->sendparam(lcd, data[i]);
        }
    }

  lcd->deselect(lcd);
}

